#!/usr/bin/env python3
"""Enhance the unified Dashboard with entity detail, quality, and snapshot diff UX."""
from __future__ import annotations

import argparse
import json
from pathlib import Path
from typing import Any

from io_utils import atomic_write_text

STYLE = r'''<style id="nkg-intelligence-style">
#nkgEntityShade{position:fixed;inset:0;background:rgba(29,31,43,.28);backdrop-filter:blur(2px);z-index:20;display:none}
#nkgEntityDrawer{position:fixed;right:0;top:0;bottom:0;width:min(600px,96vw);background:#fff;border-left:1px solid var(--line,#e2e5eb);box-shadow:-18px 0 60px rgba(31,34,47,.18);z-index:21;transform:translateX(102%);transition:transform .18s ease;overflow:auto;padding:20px}
#nkgEntityDrawer.open{transform:translateX(0)}#nkgEntityShade.open{display:block}.nkgClose{float:right;width:36px;height:36px;border:1px solid var(--line,#e2e5eb);background:#fff;color:var(--muted,#687083);border-radius:10px;font-size:19px}.nkgHero{padding:18px;border:1px solid #dcd9f7;border-radius:15px;background:linear-gradient(135deg,#fff,#f8f7ff);margin:8px 0 14px}.nkgHero h2{font-size:25px;margin:4px 0 6px}.nkgHeadline{font-size:13px;color:var(--muted,#687083);margin:5px 0 14px}.nkgKeyLine{display:grid;grid-template-columns:76px minmax(0,1fr);gap:10px;margin:10px 0}.nkgKeyLabel{color:var(--muted,#687083);font-size:12px}.nkgFirst{font-size:16px;font-weight:750;color:var(--accent,#6157d8)}.nkgChips{display:flex;gap:6px;flex-wrap:wrap}.nkgChip{border:1px solid var(--line,#e2e5eb);border-radius:999px;padding:4px 8px;background:var(--surface2,#f8f9fb);font-size:11px;color:#454c5f}.nkgBadge{border-color:#cbc7f4;background:var(--accent-soft,#eeecff);color:var(--accent,#6157d8)}.nkgDetailSection{margin:18px 0}.nkgDetailSection h3{font-size:12px;margin:0 0 9px;color:var(--muted,#687083);letter-spacing:.06em;text-transform:uppercase}.nkgDetailGrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(155px,1fr));gap:7px}.nkgMini{border:1px solid var(--line,#e2e5eb);border-radius:10px;padding:9px;background:#fff}.nkgMini b{display:block;margin-bottom:3px;font-size:12px}.nkgClickable{cursor:pointer}.nkgClickable:hover{outline:1px solid #bbb6f3;outline-offset:2px}.nkgEvidence{display:block;color:var(--accent,#6157d8);text-decoration:none;margin:5px 0;padding:8px 10px;border-radius:9px;background:var(--accent-soft,#eeecff);font-size:12px}.nkgQualityGrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:9px;margin-top:12px}.nkgQualityMetric{border:1px solid var(--line,#e2e5eb);border-radius:11px;padding:11px;background:#fff}.nkgQualityMetric strong{font-size:22px;display:block}.nkgDiffControls{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-bottom:14px}.nkgDiffControls input{max-width:120px;background:#fff;color:#171a21;border:1px solid var(--line,#e2e5eb);border-radius:8px;padding:6px 8px}.nkgAiNote{color:var(--muted,#687083);font-size:11px;margin-top:10px}.nkgDiffGroup{margin-top:16px}.nkgDiffGroup h3{font-size:13px;margin:0 0 8px}.nkgDiffEntry{display:grid;grid-template-columns:90px minmax(0,1fr);gap:10px;padding:8px 0;border-bottom:1px solid var(--line,#e2e5eb);font-size:12px}.nkgDiffEntry b{color:var(--accent,#6157d8)}
</style>'''

SCRIPT = r'''<script id="nkg-intelligence-layer">
const NKGX=__NKG_PAYLOAD__,NKG_PROFILES=NKGX.profiles?.profiles||{},NKG_QUALITY=NKGX.quality||{};let nkgCompareChapter=Math.max(min,max-50);
function nkgVis(row,c){const a=N(row?.valid_from)??0,z=N(row?.valid_to);return a<=c&&(z===null||c<=z)}
function nkgEv(id){return A(G.evidence).find(x=>x.id===id)}
function nkgProfile(id,c){const p=NKG_PROFILES[id]||{};return {headlines:A(p.headlines).filter(x=>nkgVis(x,c)),important_attributes:A(p.important_attributes).filter(x=>nkgVis(x,c)),badges:A(p.badges).filter(x=>nkgVis(x,c)),ai_authored:!!p.ai_authored}}
function nkgImportant(e,p){const raw=A(G.entities).find(x=>x.id===e.id),projected=raw?entityAt(raw,S.chapter):e,attrs=projected?.attributes||{};let rows=[];for(const x of p.important_attributes)if(Object.hasOwn(attrs,x.source_key))rows.push({label:x.label||x.source_key,value:attrs[x.source_key],reason:x.reason||''});if(!rows.length)rows=Object.entries(attrs).slice(0,6).map(([k,v])=>({label:k,value:v,reason:''}));return rows}
function nkgCurrentStates(id,c){const latest=new Map();for(const x of A(G.state_changes)){if(x.entity_id!==id||(N(x.chapter)??1e15)>c)continue;const key=String(x.facet||'状态'),old=latest.get(key);if(!old||(N(old.chapter)??0)<=(N(x.chapter)??0))latest.set(key,x)}return [...latest.entries()].map(([facet,x])=>({facet,value:x.after,chapter:x.chapter}))}
function nkgRelLabel(r,id){const other=r.source_id===id?r.target_id:r.source_id;return `${(typeof REL_LABELS!=='undefined'&&REL_LABELS[r.relation_type])||r.relation_type||'关系'} · ${S.names[other]||other}`}
function nkgOpenEntity(id){const e=S?.graph?.entities?.find(x=>x.id===id);if(!e)return;const p=nkgProfile(id,S.chapter),attrs=nkgImportant(e,p),states=nkgCurrentStates(id,S.chapter),rels=A(S.graph.relations).filter(r=>r.source_id===id||r.target_id===id).slice(0,16),events=A(S.graph.events).filter(v=>A(v.participant_ids).includes(id)).sort((a,b)=>(N(b.chapter)??0)-(N(a.chapter)??0)).slice(0,10),headline=p.headlines.at(-1)?.text||e.summary||e.description||'',first=N(e.first_chapter),badges=p.badges.map(x=>`<span class="nkgChip nkgBadge">${E(x.label)}</span>`).join('');const attrHtml=attrs.length?attrs.map(x=>`<span class=nkgChip title="${E(x.reason)}"><b>${E(x.label)}</b> ${E(typeof x.value==='object'?JSON.stringify(x.value):x.value)}</span>`).join(''):'<span class=muted>当前章节暂无可见属性</span>';const stateHtml=states.length?states.map(x=>`<div class=nkgMini><b>${E(x.facet)}</b>${E(typeof x.value==='object'?JSON.stringify(x.value):x.value)}<div class=muted>第${x.chapter}章更新</div></div>`).join(''):'<div class=muted>暂无状态变化</div>';const relHtml=rels.length?rels.map(r=>`<div class=nkgMini><b>${E(nkgRelLabel(r,id))}</b><span class=muted>${E(r.status||'')}</span></div>`).join(''):'<div class=muted>当前章节暂无活动关系</div>';const eventHtml=events.length?events.map(v=>`<div class=nkgMini><b>第${v.chapter}章 · ${E(v.title||v.type||v.id)}</b><span class=muted>${E(v.type||'')}</span></div>`).join(''):'<div class=muted>暂无已发生事件</div>';const evidence=[...new Set([...A(e.evidence_ids),...rels.flatMap(x=>A(x.evidence_ids)),...events.flatMap(x=>A(x.evidence_ids))])].map(nkgEv).filter(x=>x&&(N(x.chapter)??1e15)<=S.chapter).slice(0,14),evidHtml=evidence.length?evidence.map(x=>`<a class=nkgEvidence href="reader.html?chapter=${x.chapter}&evidence=${encodeURIComponent(x.id)}">第${x.chapter}章 · ${E(String(x.quote||'').slice(0,96))}</a>`).join(''):'<div class=muted>暂无直接证据</div>';document.getElementById('nkgEntityBody').innerHTML=`<button class=nkgClose id=nkgCloseEntity>×</button><div class=nkgHero><div class=eyebrow>${E((typeof TYPE_LABELS!=='undefined'&&TYPE_LABELS[e.type])||e.type||'实体')}</div><h2>${E(e.name||e.id)}</h2>${headline?`<div class=nkgHeadline>${E(headline)}</div>`:''}<div class=nkgKeyLine><span class=nkgKeyLabel>首次出现</span><span class=nkgFirst>${first===null?'未知':`第 ${first} 章`}</span></div><div class=nkgKeyLine><span class=nkgKeyLabel>重要属性</span><div class=nkgChips>${attrHtml}</div></div>${badges?`<div class=nkgChips>${badges}</div>`:''}<div class=nkgAiNote>${p.ai_authored?'重要属性由 AI display profile 按当前作品判断；事实值仍来自当前章节快照。':'未提供 AI display profile；当前使用可见属性做中性降级。'}</div></div><div class=nkgDetailSection><h3>当前状态</h3><div class=nkgDetailGrid>${stateHtml}</div></div><div class=nkgDetailSection><h3>当前关系</h3><div class=nkgDetailGrid>${relHtml}</div></div><div class=nkgDetailSection><h3>最近事件</h3><div class=nkgDetailGrid>${eventHtml}</div></div><div class=nkgDetailSection><h3>证据</h3>${evidHtml}</div>`;document.getElementById('nkgEntityDrawer').classList.add('open');document.getElementById('nkgEntityShade').classList.add('open');document.getElementById('nkgCloseEntity').onclick=nkgCloseEntity}
function nkgCloseEntity(){document.getElementById('nkgEntityDrawer').classList.remove('open');document.getElementById('nkgEntityShade').classList.remove('open')}
function nkgBind(){if(active==='repo')document.querySelectorAll('[data-entity-id]').forEach(row=>{const id=row.dataset.entityId;if(id){row.classList.add('nkgClickable');row.onclick=()=>nkgOpenEntity(id)}});if(active==='graph'&&cy&&!cy.__nkgEntityBound){cy.__nkgEntityBound=true;cy.on('tap','node',evt=>nkgOpenEntity(evt.target.id()))}}
function nkgAppendQuality(){const q=NKG_QUALITY;if(!q||!q.evidence)return;const ratio=q.evidence.ratio==null?'—':`${Math.round(q.evidence.ratio*100)}%`,root=document.querySelector('#main section');if(!root||root.querySelector('.nkgQualityGrid'))return;root.insertAdjacentHTML('beforeend',`<div class=nkgQualityGrid><div class=nkgQualityMetric><strong>${ratio}</strong>证据引用覆盖</div><div class=nkgQualityMetric><strong>${q.temporal_provenance?.gap_count??0}</strong>时序来源缺口</div><div class=nkgQualityMetric><strong>${q.review?.unresolved_count??0}</strong>未解决审计项</div><div class=nkgQualityMetric><strong>${q.invariants?.warning_count??0}</strong>语义不变量警告</div><div class=nkgQualityMetric><strong>${q.invariants?.error_count??0}</strong>语义不变量错误</div></div>`)}
function nkgIdSet(rows){return new Set(A(rows).map(x=>x.id).filter(Boolean))}function nkgDiffBlock(title,rows,renderRow){return rows.length?`<div class=nkgDiffGroup><h3>${E(title)} · ${rows.length}</h3>${rows.slice(0,90).map(renderRow).join('')}</div>`:''}
function nkgRenderChanges(){const hi=S.chapter,lo=Math.min(Math.max(Number(nkgCompareChapter)||min,min),hi),old=snapshotAt(lo),oldEnt=nkgIdSet(old.graph.entities),oldEv=nkgIdSet(old.graph.events),entities=S.graph.entities.filter(x=>!oldEnt.has(x.id)),events=S.graph.events.filter(x=>!oldEv.has(x.id)),states=A(G.state_changes).filter(x=>(N(x.chapter)??0)>lo&&(N(x.chapter)??0)<=hi),oldRel=Object.fromEntries(old.graph.relations.map(x=>[x.id,`${x.status||''}|${x.valid_to??''}`])),relChanges=S.graph.relations.filter(x=>oldRel[x.id]!==`${x.status||''}|${x.valid_to??''}`),oldCom=Object.fromEntries(A(old.views.commitments).map(x=>[x.id,x.status])),comChanges=A(S.views.commitments).filter(x=>oldCom[x.id]!==x.status);mainEl.innerHTML=`<section>${typeof viewHead==='function'?viewHead('章节变化','比较两个章节快照之间真正发生的结构变化。','Snapshot diff'):''}<div class=nkgDiffControls><label>对比第 <input id=nkgCompare type=number min=${min} max=${hi} value=${lo}> 章</label><span class=muted>→ 当前第 ${hi} 章</span></div><div class=grid><div class="card metric-card"><div class=metric>${entities.length}</div><div class=muted>新增实体</div></div><div class="card metric-card"><div class=metric>${events.length}</div><div class=muted>新增事件</div></div><div class="card metric-card"><div class=metric>${states.length}</div><div class=muted>状态变化</div></div><div class="card metric-card"><div class=metric>${relChanges.length}</div><div class=muted>关系变化</div></div><div class="card metric-card"><div class=metric>${comChanges.length}</div><div class=muted>承诺状态变化</div></div></div>${nkgDiffBlock('新增实体',entities,x=>`<div class=nkgDiffEntry><b>第${x.first_chapter??'?'}章</b><span>${E(x.name)} · ${E(x.type||'')}</span></div>`)}${nkgDiffBlock('新增事件',events,x=>`<div class=nkgDiffEntry><b>第${x.chapter}章</b><span>${E(x.title||x.type||x.id)}</span></div>`)}${nkgDiffBlock('状态变化',states,x=>`<div class=nkgDiffEntry><b>第${x.chapter}章</b><span>${E(S.names[x.entity_id]||x.entity_id)} · ${E(x.facet)} → ${E(typeof x.after==='object'?JSON.stringify(x.after):x.after)}</span></div>`)}${nkgDiffBlock('关系变化',relChanges,x=>`<div class=nkgDiffEntry><b>${E((typeof REL_LABELS!=='undefined'&&REL_LABELS[x.relation_type])||x.relation_type)}</b><span>${E(S.names[x.source_id]||x.source_id)} ↔ ${E(S.names[x.target_id]||x.target_id)}</span></div>`)}${nkgDiffBlock('承诺变化',comChanges,x=>`<div class=nkgDiffEntry><b>第${x.created_chapter??'?'}章</b><span>${E(x.terms)} · ${E(x.status||'')}</span></div>`)}</section>`;document.getElementById('nkgCompare').onchange=e=>{nkgCompareChapter=Number(e.target.value);nkgRenderChanges()}}
const nkgBaseRender=render;render=function(){if(active==='changes'){nkgRenderChanges();return}nkgBaseRender();setTimeout(()=>{nkgBind();if(active==='audit')nkgAppendQuality()},0)};document.body.insertAdjacentHTML('beforeend','<div id=nkgEntityShade></div><aside id=nkgEntityDrawer><div id=nkgEntityBody></div></aside>');document.getElementById('nkgEntityShade').onclick=nkgCloseEntity;const nkgChangeButton=document.createElement('button');nkgChangeButton.textContent='变化';nkgChangeButton.dataset.panel='changes';nkgChangeButton.onclick=()=>{active='changes';document.querySelectorAll('#tabs button').forEach(x=>x.classList.toggle('on',x===nkgChangeButton));render()};const nkgAudit=[...tabsEl.querySelectorAll('button')].find(x=>x.textContent==='审计');tabsEl.insertBefore(nkgChangeButton,nkgAudit||null);nkgBind();
</script>'''


def enhance_html(source: str, profiles: dict[str, Any], quality: dict[str, Any] | None = None) -> str:
    if 'id="nkg-intelligence-layer"' in source:
        return source
    payload = json.dumps({"profiles": profiles, "quality": quality or {}}, ensure_ascii=False, separators=(",", ":")).replace("</", "<\\/")
    if "</head>" not in source or "</body>" not in source:
        raise ValueError("dashboard HTML is missing </head> or </body>")
    return source.replace("</head>", STYLE + "</head>", 1).replace("</body>", SCRIPT.replace("__NKG_PAYLOAD__", payload) + "</body>", 1)


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--dashboard", required=True, type=Path)
    parser.add_argument("--profiles", required=True, type=Path)
    parser.add_argument("--quality", type=Path)
    args = parser.parse_args()
    source = args.dashboard.read_text(encoding="utf-8")
    profiles = json.loads(args.profiles.read_text(encoding="utf-8"))
    quality = json.loads(args.quality.read_text(encoding="utf-8")) if args.quality else None
    atomic_write_text(args.dashboard, enhance_html(source, profiles, quality))
    print(json.dumps({"dashboard": str(args.dashboard), "entity_detail": True, "snapshot_diff": True, "quality_overlay": quality is not None, "reader_first_theme": True}, ensure_ascii=False))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
